// Writes src/manifest/index.ts and src/components/index.ts from the block folders in src/blocks.
// Run `pnpm --filter @repo/blocks registry` after adding a block. The tests fail if you forget.
import { readdirSync, writeFileSync } from 'node:fs'

const root = new URL('../src/', import.meta.url)
const dirs = readdirSync(new URL('blocks/', root), { withFileTypes: true })
  .filter((d) => d.isDirectory())
  .map((d) => d.name)
  .sort()
const ident = (d: string) => d.replace(/-([a-z0-9])/g, (_, c: string) => c.toUpperCase())
const head =
  '// Generated by scripts/registry.ts from the folders in src/blocks. Do not edit by hand.\n'

writeFileSync(
  new URL('manifest/index.ts', root),
  `${head}// Every block manifest in the library. Pure data: the pipeline imports this, never the components.
import type { BlockManifest } from './contract.ts'
${dirs.map((d) => `import ${ident(d)} from '../blocks/${d}/manifest.ts'`).join('\n')}

export * from './contract.ts'

export const manifests: readonly BlockManifest[] = [
${dirs.map((d) => `  ${ident(d)},`).join('\n')}
] as readonly BlockManifest[]
`,
)

writeFileSync(
  new URL('components/index.ts', root),
  `${head}// Block components by block type. Imported by the renderer only, never by the pipeline.
import type { ComponentType } from 'react'
import type { BlockProps } from '../kit/index.tsx'
import { manifests } from '../manifest/index.ts'
${dirs.map((d) => `import ${ident(d)} from '../blocks/${d}/component.tsx'`).join('\n')}

export * from '../kit/index.tsx'

const byFolder = [${dirs.map(ident).join(', ')}]

// biome-ignore lint/suspicious/noExplicitAny: keyed by block type; each component checks its own section's content
export const components: Record<string, ComponentType<BlockProps<any>>> = Object.fromEntries(
  manifests.map((m, i) => [m.type, byFolder[i]]),
) as Record<string, ComponentType<BlockProps<any>>>
`,
)
console.log(`registry: ${dirs.length} blocks`)
